<?php

/**
 * Hand-written code. NOT generated by Speakeasy. Safe from regeneration.
 *
 * @see docs/REGENERATION.md
 */

declare(strict_types=1);

namespace Factuarea\Sdk\Custom\Idempotency;

use GuzzleHttp\ClientInterface;
use GuzzleHttp\Promise\PromiseInterface;
use Psr\Http\Message\RequestInterface;
use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\UriInterface;

/**
 * Adds a retry-stable key after Speakeasy has assembled operation headers.
 *
 * Generated operations pass explicit headers in Guzzle options rather than in
 * the PSR request seen by before-request hooks. Inspecting both here preserves
 * the caller's Idempotency-Key instead of replacing it with a random one.
 */
final class IdempotencyClient implements ClientInterface
{
    /** @var \WeakMap<RequestInterface, string> */
    private \WeakMap $generatedKeys;

    public function __construct(private readonly ClientInterface $client)
    {
        $this->generatedKeys = new \WeakMap();
    }

    /** @param array<string, mixed> $options */
    public function send(RequestInterface $request, array $options = []): ResponseInterface
    {
        return $this->client->send($request, $this->withIdempotencyKey($request, $options));
    }

    /** @param array<string, mixed> $options */
    public function sendAsync(RequestInterface $request, array $options = []): PromiseInterface
    {
        return $this->client->sendAsync($request, $this->withIdempotencyKey($request, $options));
    }

    /**
     * @param  string|UriInterface  $uri
     * @param  array<string, mixed>  $options
     */
    public function request(string $method, $uri, array $options = []): ResponseInterface
    {
        return $this->client->request($method, $uri, $this->withIdempotencyKey(new \GuzzleHttp\Psr7\Request($method, $uri), $options));
    }

    /**
     * @param  string|UriInterface  $uri
     * @param  array<string, mixed>  $options
     */
    public function requestAsync(string $method, $uri, array $options = []): PromiseInterface
    {
        return $this->client->requestAsync($method, $uri, $this->withIdempotencyKey(new \GuzzleHttp\Psr7\Request($method, $uri), $options));
    }

    public function getConfig(?string $option = null): mixed
    {
        return $this->client->getConfig($option);
    }

    /**
     * @param  array<string, mixed>  $options
     * @return array<string, mixed>
     */
    private function withIdempotencyKey(RequestInterface $request, array $options): array
    {
        if (! in_array(strtoupper($request->getMethod()), ['POST', 'PUT', 'PATCH', 'DELETE'], true)
            || $request->hasHeader('Idempotency-Key')
            || self::hasHeader($options['headers'] ?? [], 'Idempotency-Key')
            || self::hasHeader($this->client->getConfig('headers') ?? [], 'Idempotency-Key')) {
            return $options;
        }

        $this->generatedKeys[$request] ??= IdempotencyHook::uuidV4();
        $options['headers']['Idempotency-Key'] = $this->generatedKeys[$request];

        return $options;
    }

    private static function hasHeader(mixed $headers, string $name): bool
    {
        if (! is_array($headers)) {
            return false;
        }

        foreach (array_keys($headers) as $headerName) {
            if (is_string($headerName) && strcasecmp($headerName, $name) === 0) {
                return true;
            }
        }

        return false;
    }
}
